\begin{hbtheorem}{thm:p10-countable-atomless-uniqueness}{proved=annex:p10.atomless.2}{Uniqueness of the countable atomless Boolean algebra}
Any two nontrivial countable atomless Boolean algebras are isomorphic.
More generally, every isomorphism between finite subalgebras of two
such algebras extends to an isomorphism of the whole algebras.
\end{hbtheorem}

\begin{hbdefinition}{def:p12-lcf-architecture}{LCF architecture}
An \emph{LCF architecture} is the programming discipline in which values of an
abstract theorem type can be constructed only by a small set of trusted
primitive inference functions, while untrusted tactics compose those
functions.  The identifier \(\mathsf{LCF}\) is necessary to name that
constructor boundary, stands for an implementation architecture rather than a
logic, and is not synonymous with exporting a portable proof object.  The
distinction is used in Theorem~\ref{thm:p12-lcf-boundary} and
Table~\ref{tab:p12-assistant-landscape}
\cite{GordonMilnerWadsworth1979}.
\index{LCF architecture}
\end{hbdefinition}

\begin{hbtheorem}{thm:p02-decidability}{cited=EbbinghausFlumThomas1994}{Decidability of classical propositional logic}
There is a terminating algorithm which, on finite encoded inputs, decides
whether a propositional formula is satisfiable or valid, whether two formulas
are logically equivalent, and whether a finite set \(\Gamma\) semantically
entails a formula \(\varphi\).
\end{hbtheorem}

\begin{hbtheorem}{thm:p02-sat-np-complete}{cited=AroraBarak2009}{SAT NP-completeness}
\(\mathsf{SAT}\) is \(\mathsf{NP}\)-complete under polynomial-time many-one
reductions.
\end{hbtheorem}
